
const $=s=>document.querySelector(s);
const E=s=>s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const N=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const KB=[
{t:'Paludisme',c:'m',k:['paludisme','palu','moustique','frisson'],a:'Le paludisme se transmet par les piqûres de moustique. Signes fréquents : fièvre, frissons, maux de tête, courbatures. Un test de diagnostic rapide en structure de santé permet de le confirmer. Prévention : moustiquaire imprégnée, répulsif, éviter les eaux stagnantes.',s:'vous avez de la fièvre, surtout chez un enfant ou une femme enceinte : ne tardez pas.'},
{t:'Fièvre',c:'m',k:['fievre','temperature','chaud'],a:'Reposez-vous, buvez régulièrement, habillez-vous légèrement et aérez la pièce.',s:'la fièvre dure plus de 3 jours, concerne un nourrisson, ou s’accompagne de convulsions, raideur de la nuque, confusion ou difficultés à respirer.'},
{t:'Diarrhée et déshydratation',c:'m',k:['diarrhee','deshydrat','vomi','selles'],a:'Le principal risque est la déshydratation. Buvez souvent de petites quantités ; les sels de réhydratation orale (SRO) sont recommandés. Lavez-vous les mains et utilisez une eau propre.',s:'il y a du sang dans les selles, des vomissements répétés, une forte fièvre, ou si la personne est un enfant ou âgée (bouche sèche, urines rares).'},
{t:'Hypertension',c:'m',k:['hypertension','tension','arterielle'],a:'Elle est souvent sans symptômes. Réduisez le sel, bougez régulièrement, limitez tabac et alcool, et faites contrôler votre tension.',s:'maux de tête intenses, douleur thoracique ou malaise : consultez en urgence.'},
{t:'Diabète',c:'m',k:['diabete','glycemie','sucre dans'],a:'Signes possibles : soif intense, urines fréquentes, fatigue, amaigrissement. Seul un test de glycémie confirme. Alimentation équilibrée, activité physique et suivi médical aident à le contrôler.',s:'vous remarquez ces signes ou avez des antécédents familiaux.'},
{t:'Lavage des mains',c:'m',k:['main','hygiene','savon','microbe','laver'],a:'Lavez-vous les mains à l’eau et au savon pendant au moins 20 secondes : avant de manger ou cuisiner, après les toilettes, après avoir toussé ou éternué.',s:'—'},
{t:'Toux et grippe',c:'m',k:['toux','grippe','rhume','gorge','nez'],a:'Reposez-vous, hydratez-vous, couvrez-vous la bouche en toussant et aérez les pièces.',s:'vous avez du mal à respirer, une toux de plus de 2 semaines, des crachats avec du sang ou une fièvre persistante.'},
{t:'Maux de tête',c:'m',k:['tete','migraine','cephal'],a:'Buvez de l’eau, reposez-vous, dormez suffisamment et limitez les écrans.',s:'la douleur est brutale et violente, suit un choc, ou s’accompagne de fièvre, raideur de la nuque ou troubles de la vision.'},
{t:'Alimentation équilibrée',c:'m',k:['alimentation','manger','nutrition','regime','repas'],a:'Variez : céréales, légumineuses, légumes, fruits et protéines. Limitez sucre, sel et fritures, et buvez de l’eau.',s:'vous avez une maladie ou un besoin particulier : demandez un avis personnalisé.'},
{t:'Sommeil',c:'w',k:['sommeil','dormir','insomnie','nuit'],a:'Gardez des horaires réguliers, évitez écrans et caféine le soir, et rendez la chambre calme et sombre.',s:'les difficultés durent plus de 3 semaines.'},
{t:'Stress et examens',c:'w',k:['stress','examen','revision','concours','pression'],a:'Découpez les révisions en petites étapes, faites des pauses, dormez, bougez et parlez-en à un proche. Essayez l’exercice de respiration de l’onglet Bien-être.',s:'le stress vous empêche de dormir, de manger ou d’étudier.'},
{t:'Anxiété',c:'w',k:['anxi','angoiss','panique','peur','inquiet'],a:'L’anxiété est une réaction fréquente. Respirez lentement, nommez ce que vous ressentez, réduisez la caféine et gardez des routines simples.',s:'elle dure, gêne votre quotidien ou provoque des crises de panique.'},
{t:'Tristesse',c:'w',k:['triste','deprim','cafard','pleur','moral','decourag'],a:'La tristesse peut suivre une difficulté. Parlez à une personne de confiance, gardez vos routines et une activité douce chaque jour.',s:'elle dure plus de 2 semaines ou vous fait perdre tout intérêt pour vos activités.'},
{t:'Solitude',c:'w',k:['seul','solitude','isole','parler','ecoute','personne'],a:'Merci de vous exprimer, c’est un premier pas. Je ne suis pas psychologue, mais je peux vous écouter. Contactez aussi un proche ou un ami aujourd’hui, même par un simple message.',s:'vous vous sentez isolé(e) depuis longtemps.'},
{t:'Fatigue',c:'w',k:['fatigu','epuis','energie','crev'],a:'Vérifiez votre sommeil, vos repas et votre hydratation, et prenez de vraies pauses.',s:'la fatigue persiste plus de 2 semaines : une cause médicale (anémie par exemple) est possible.'}
];
const CRI='<p>Ce que vous vivez compte, et vous méritez d’être soutenu(e) dès maintenant.</p><p>Ne restez pas seul(e) : contactez tout de suite une personne de confiance près de vous. Si vous êtes en danger immédiat, appelez le SAMU <b>1515</b> ou les sapeurs-pompiers <b>18</b>, ou rendez-vous aux urgences les plus proches.</p>';
const URG='<p><b>Cette situation peut être grave.</b> Appelez sans attendre le SAMU <b>1515</b> ou les sapeurs-pompiers <b>18</b>, ou rendez-vous aux urgences les plus proches.</p>';
const tel=(n,l)=>`<a class="b" href="tel:${n}">${l}</a>`;
const SOS=tel(1515,'Appeler le SAMU 1515')+tel(18,'Appeler les pompiers 18');
const fiche=e=>`<p><b>${e.t}</b></p><p>${e.a}</p>${e.s==='—'?'':`<p><b>${e.c==='m'?'Consultez si :':'Parlez-en à un professionnel si :'}</b> ${e.s}</p>`}`;
function reply(q){const n=N(q);
if(/suicid|me tuer|en finir|mourir|faire du mal|plus envie de vivre|plus vivre/.test(n))return{h:CRI+SOS,u:1};
if(/douleur.*(poitrine|thorac)|difficulte.*respir|perte de connaissance|convuls|saignement abondant|inconscient|etouff/.test(n))return{h:URG+SOS,u:1};
let b=null,m=0;KB.forEach(e=>{const s=e.k.filter(w=>n.includes(w)).length;if(s>m){m=s;b=e}});
if(b)return{h:fiche(b)};
if(/^(bonjour|salut|bonsoir|salam|hello|coucou)/.test(n))return{h:'<p>Bonjour ! Posez-moi une question sur votre santé ou parlez-moi de ce que vous ressentez.</p>'};
if(/merci/.test(n))return{h:'<p>Avec plaisir. Prenez soin de vous.</p>'};
return{h:'<p>Je n’ai pas de fiche sur ce sujet. Essayez un autre mot (fièvre, stress, sommeil…), consultez l’onglet Fiches, ou utilisez l’onglet Orienter pour savoir qui consulter.</p>'}}
let tab='home',chat=[],o={s:0,a:[]},bt=null,H=[];
try{H=JSON.parse(localStorage.getItem('sutura_h')||'[]')}catch(e){H=[]}
const save=()=>{try{localStorage.setItem('sutura_h',JSON.stringify(H))}catch(e){}};
const TABS=[['home','⌂','Accueil'],['fiches','✚','Fiches'],['chat','☏','Assistant'],['orient','⌖','Orienter'],['well','♡','Bien-être']];
function go(t){tab=t;render()}
function msgs(){return chat.map(m=>`<div class="m ${m.u?'u':'a'}">${m.h}</div>`).join('')}
function draw(){$('#ms').innerHTML=msgs();const c=$('#ch');if(c)c.remove();window.scrollTo(0,document.body.scrollHeight)}
function send(t){const i=$('#q');t=(t||i.value).trim();if(!t)return false;chat.push({u:1,h:E(t)});if(i)i.value='';draw();setTimeout(()=>{const r=reply(t);chat.push({h:r.h});draw()},350);return false}
function ecoute(){if(!chat.length)chat.push({h:'<p>Bienvenue dans l’espace d’écoute. Comment vous sentez-vous aujourd’hui ?</p><p class="mu">Je ne suis pas psychologue et je ne pose aucun diagnostic. En cas d’urgence : SAMU 1515 ou pompiers 18.</p>'});go('chat')}
function list(q){const n=N(q||'');$('#fl').innerHTML=KB.filter(e=>!n||N(e.t+e.k.join(' ')).includes(n)).map(e=>`<details class="c"><summary>${e.t}<span class="pill">${e.c==='m'?'Médical':'Bien-être'}</span></summary>${fiche(e)}<p class="mu">Contenu de démonstration, à faire valider par un professionnel de santé partenaire.</p></details>`).join('')||'<p class="mu">Aucune fiche trouvée.</p>'}
function oa(v){o.a.push(v);o.s++;render()}
function oreset(){o={s:0,a:[]};render()}
function btn(arr,fn){return arr.map(x=>`<button class="b s" onclick="${fn}('${x}')">${x}</button>`).join('')}
function oview(){const[s0,ty,du]=o.a;
if(o.s===0)return`<h2>Orientation</h2><div class="c"><p>Présentez-vous l’un de ces signes ?</p><ul><li>difficulté à respirer</li><li>douleur à la poitrine</li><li>perte de connaissance ou convulsions</li><li>saignement abondant</li><li>pensées de vous faire du mal</li></ul>${btn(['Oui','Non'],'oa')}</div>`;
if(s0==='Oui')return`<h2>Orientation</h2><div class="alert">${URG}</div>${SOS}<button class="b s" onclick="oreset()">Recommencer</button>`;
if(o.s===1)return`<h2>Orientation</h2><div class="c"><p>Quelle est votre préoccupation principale ?</p>${btn(['Physique','Émotionnelle','Les deux'],'oa')}</div>`;
if(o.s===2)return`<h2>Orientation</h2><div class="c"><p>Depuis combien de temps ?</p>${btn(['Moins d’une semaine','Plus d’une semaine'],'oa')}</div>`;
const l=du==='Plus d’une semaine';let r;
if(ty==='Physique')r=l?'<b>Consultez un médecin cette semaine.</b> Une consultation permet de comprendre la cause et d’être soigné(e) à temps.':'<b>Médecin généraliste ou centre de santé si cela ne s’améliore pas.</b> En attendant : repos, hydratation, et surveillance des signes d’alerte (voir Fiches).';
else if(ty==='Émotionnelle')r=l?'<b>Un psychologue est recommandé.</b> Parlez-en aussi à un proche de confiance.':'<b>Parlez-en à un proche et essayez l’espace d’écoute.</b> Si cela persiste, un psychologue pourra vous aider.';
else r='<b>Consultez un médecin et un psychologue.</b> Le corps et le moral sont liés : un suivi des deux est utile.';
return`<h2>Orientation</h2><div class="c"><p>${r}</p><p class="mu">Cette orientation est indicative et ne remplace pas l’avis d’un professionnel.</p></div><button class="b" onclick="ecoute()">Parler à l’assistant</button><button class="b s" onclick="oreset()">Recommencer</button>`}
const ML=['Très mal','Mal','Moyen','Bien','Très bien'];
function mood(v){const d=new Date().toISOString().slice(0,10);H=H.filter(x=>x.d!==d);H.push({d,v});H=H.slice(-30);save();render()}
function stopB(){clearTimeout(bt);bt=null}
function breath(){const r=$('#ring');if(!r)return;if(bt){stopB();render();return}$('#bb').textContent='Arrêter';
const P=[['Inspirez',4,1.35],['Retenez',4,1.35],['Expirez',6,1]];let i=0;
(function step(){const[t,s,sc]=P[i%3];r.textContent=t;r.style.transitionDuration=s+'s';r.style.transform='scale('+sc+')';i++;bt=setTimeout(step,s*1000)})()}
function wview(){const L=H.slice(-7);const t=new Date().toISOString().slice(0,10);const td=H.find(x=>x.d===t);
return`<h2>Comment vous sentez-vous ?</h2><div class="moods">${ML.map((x,i)=>`<button onclick="mood(${i+1})">${x}</button>`).join('')}</div>${td?`<p class="mu">Aujourd’hui : ${ML[td.v-1]}.${td.v<=2?' Vous n’êtes pas seul(e) : parlez-en à un proche ou à l’assistant.':''}</p>`:''}
${td&&td.v<=2?'<button class="b s" onclick="ecoute()">Parler à l’assistant</button>':''}
<div class="c"><b>Mon suivi (7 derniers jours)</b>${L.length?`<div class="bars">${L.map(x=>`<div><i style="height:${x.v*16}px"></i>${x.d.slice(8)}/${x.d.slice(5,7)}</div>`).join('')}</div>`:'<p class="mu">Aucune donnée. Enregistrez votre humeur ci-dessus.</p>'}</div>
<div class="c"><b>Respiration guidée</b><p class="mu">Inspirez 4 s, retenez 4 s, expirez 6 s. Répétez pendant quelques minutes.</p><div class="ring" id="ring">Prêt(e) ?</div><button class="b" id="bb" onclick="breath()">Commencer</button></div>`}
function hview(){return`<h1>${PR?'Bonjour, '+E(PR.p):'Prenez soin de vous'}</h1><p class="mu">Information, écoute et orientation santé.</p>
<div class="alert">Urgence ? SAMU <b>1515</b> · Sapeurs-pompiers <b>18</b></div>${pcard()}
<div class="g2"><button class="c" onclick="go('fiches')"><b>✚ Informations médicales</b><div class="mu">Prévention et santé physique</div></button><button class="c" onclick="ecoute()"><b>♡ Soutien psychologique</b><div class="mu">Écoute et bien-être</div></button><button class="c" onclick="go('orient')"><b>⌖ Orientation</b><div class="mu">Médecin ou psychologue ?</div></button><button class="c" onclick="go('well')"><b>☺ Bien-être</b><div class="mu">Humeur et respiration</div></button></div>
<button class="c" onclick="go('tech')"><b>⚙ Dossier technique</b><div class="mu">Solution, prototype, faisabilité, innovation</div></button><button class="c" onclick="go('legal')"><b>§ Informations légales</b><div class="mu">Conditions, confidentialité, mes données</div></button><details class="c"><summary>À propos</summary><p>Sutura Santé — Groupe 104. Une plateforme qui réunit information médicale et premier soutien psychologique, adaptée aux réalités sénégalaises.</p><p class="mu">Outil d’information et d’orientation : il ne remplace pas une consultation médicale ou psychologique et ne pose aucun diagnostic. Le profil santé et le suivi d’humeur du prototype restent sur cet appareil. Les données de compte et de rendez-vous sont transmises au serveur.</p><button class="b s" onclick="wipe()">Effacer mes données</button></details>`}
const tview=()=>`<button class="chip" onclick="go('home')">← Accueil</button><h2>Dossier technique</h2>
<div class="c"><b>1. Solution technologique</b><p>Application web mobile installable (PWA) : HTML, CSS et JavaScript, sans serveur de calcul. Deux services réunis : informations médicales et soutien psychologique, avec une orientation vers les professionnels.</p></div>
<div class="c"><b>2. Prototype</b><p>Ce prototype est fonctionnel. Parcours :</p><ul><li>Accueil : urgences et 4 entrées</li><li>Fiches : 15 contenus avec recherche</li><li>Assistant : réponse selon les mots-clés</li><li>Orientation : 3 questions, puis résultat</li><li>Bien-être : humeur et respiration guidée</li></ul></div>
<div class="c"><b>3. Faisabilité technique</b><p><b>Déjà réalisé :</b> interface, moteur de réponses, détection d’urgence, orientation, suivi d’humeur.</p><p><b>À prévoir :</b> serveur et base de contenus, validation des fiches par des médecins et psychologues, version wolof, formalités auprès de la CDP.</p><p><b>Contrainte locale :</b> connexion limitée. La page est très légère (moins de 25 Ko) et ne dépend d’aucun service externe.</p></div>
<div class="c"><b>4. Innovation technologique</b><ul><li>Santé physique et mentale dans une seule plateforme</li><li>Réponses issues de fiches contrôlées : pas de diagnostic inventé</li><li>Détection automatique des urgences et des signes de détresse, avec appel direct au 1515 ou au 18</li><li>Confidentialité par conception : les données restent sur l’appareil</li></ul></div>
<div class="c"><b>5. Conformité intégrée</b><ul><li>Écran de consentement et avertissement à l’ouverture et au début de chaque conversation</li><li>Protocole d’urgence : mots-clés d’alerte, numéros 1515 et 18</li><li>Conditions, confidentialité et mentions légales consultables</li><li>Droits des utilisateurs : accès, rectification, suppression, retrait du consentement</li><li>Aucune donnée envoyée hors de l’appareil</li></ul></div>
<div class="c"><b>Démonstration conseillée (2 min)</b><ol><li>Accueil : montrer l’encadré d’urgence</li><li>Assistant : « J’ai de la fièvre »</li><li>Assistant : « Je me sens triste »</li><li>Orientation : répondre Non, Physique, Plus d’une semaine</li><li>Bien-être : choisir une humeur, lancer la respiration</li></ol></div>`;
let OK=false,P=false,PR=null;try{OK=localStorage.getItem('sutura_ok')==='1';PR=JSON.parse(localStorage.getItem('sutura_p')||'null')}catch(e){}
const fmt=t=>String(t).replace('.',',');
function wipe(){H=[];PR=null;save();try{localStorage.removeItem('sutura_p')}catch(e){}render()}
function psave(){const g=i=>$('#'+i).value.trim();const f=i=>parseFloat(g(i).replace(',','.'));const o=v=>isNaN(v)?null:v;const r={p:g('pp'),n:g('pn'),a:f('pa'),w:o(f('pw')),t:o(f('pt'))};let e='';
if(!r.p||!r.n)e='Indiquez votre prénom et votre nom.';else if(!(r.a>=0&&r.a<=120))e='Âge invalide (0 à 120 ans).';else if(r.w!==null&&!(r.w>=1&&r.w<=300))e='Poids invalide (en kg).';else if(r.t!==null&&!(r.t>=30&&r.t<=45))e='Température invalide (entre 30 et 45 °C).';
if(!e&&!$('#pc').checked)e='Cochez la case pour accepter et continuer.';
if(e){const x=$('#pe');x.textContent=e;x.style.display='block';return}
PR=r;try{localStorage.setItem('sutura_p',JSON.stringify(r))}catch(x){}if(!OK){OK=true;try{localStorage.setItem('sutura_ok','1')}catch(x){}}P=true;render()}
function tnote(){const t=PR.t,a=PR.a,v=fmt(t);let m,u=0;
if(t>=41){m='Température très élevée ('+v+' °C). Appelez le SAMU 1515 ou rendez-vous aux urgences.';u=1}
else if(t>=39.5)m='Forte fièvre ('+v+' °C). Consultez rapidement un médecin ou un centre de santé.';
else if(t>=38)m='Fièvre ('+v+' °C). Reposez-vous et buvez régulièrement.'+(a<=2||a>=65?' À votre âge, consultez un médecin sans attendre.':' Consultez si elle dure plus de 3 jours.');
else if(t<35)m='Température basse ('+v+' °C). Réchauffez-vous et consultez rapidement un professionnel de santé.';
else m='Pas de fièvre à '+v+' °C.';
return{m,u}}
function pcard(){if(!PR)return'';const x=PR.t==null?null:tnote();return`<div class="${x&&x.u?'alert':'c'}"><b>${E(PR.p)} ${E(PR.n)} · ${PR.a} ans${PR.w==null?'':' · '+fmt(PR.w)+' kg'}</b><p>${x?x.m:'Ajoutez votre température pour recevoir un avis.'}</p><p class="mu">Indication générale, qui ne remplace pas l’avis d’un professionnel.${PR.a<18?' Parlez-en à un adulte de confiance.':''}</p>${x&&x.u?SOS:''}<button class="b s" onclick="P=false;render()">Mettre à jour mon profil</button></div>`}
const pform=()=>{const p=PR||{};const f=(i,l,v,m)=>`<label class="f"><span>${l}</span><input id="${i}" value="${E(String(v==null?'':v))}" ${m}></label>`;return`<h1>Faisons connaissance</h1><p class="mu">Ces informations restent sur votre appareil et servent à personnaliser vos conseils.</p><div class="c">${f('pp','Prénom',p.p,'autocomplete="given-name"')}${f('pn','Nom',p.n,'autocomplete="family-name"')}${f('pa','Âge (années)',p.a,'inputmode="numeric"')}${f('pw','Poids (kg), facultatif',p.w,'inputmode="decimal"')}${f('pt','Température du corps (°C), facultatif',p.t,'inputmode="decimal" placeholder="ex. 36,8"')}<div class="c" style="background:var(--bg)"${OK?' hidden':''}><ul class="mu"><li>Sutura Santé informe, écoute et oriente : il ne remplace pas une consultation et ne pose aucun diagnostic.</li><li>Urgence : SAMU 1515 ou pompiers 18.</li><li>Vos informations restent sur votre appareil et peuvent être effacées à tout moment.</li><li>Moins de 18 ans : demandez l’accord d’un parent ou tuteur.</li></ul><label class="f" style="display:flex;gap:10px;align-items:center"><input type="checkbox" id="pc" style="width:28px;height:28px;flex:none;margin:0"${OK?' checked':''}><span style="color:var(--tx);font-size:15px;margin:0">J’accepte et je continue</span></label></div><div class="alert" id="pe" style="display:none"></div><button class="b" onclick="psave()">Continuer</button></div><p class="mu">Utilisez un thermomètre si possible pour mesurer votre température.</p>`};
function accept(){OK=true;try{localStorage.setItem('sutura_ok','1')}catch(e){}render()}
function withdraw(){H=[];PR=null;P=false;save();OK=false;chat=[];try{localStorage.removeItem('sutura_ok');localStorage.removeItem('sutura_p')}catch(e){}render()}
const gate=()=>`<h1>Avant de commencer</h1><p class="mu">Merci de lire ces points essentiels.</p><div class="c"><ul><li>Sutura Santé informe, écoute et oriente. Il ne remplace pas une consultation médicale ou psychologique.</li><li>Il ne pose aucun diagnostic et ne prescrit aucun médicament.</li><li>En cas d’urgence : SAMU <b>1515</b> ou pompiers <b>18</b>.</li><li>Votre profil et votre suivi d’humeur sont enregistrés uniquement sur votre appareil. Vous pouvez les effacer à tout moment.</li><li>Si vous avez moins de 18 ans, demandez l’accord d’un parent ou d’un tuteur.</li></ul></div><button class="b" onclick="accept()">J’accepte et je continue</button><p class="mu">Version de démonstration. Vous pourrez modifier ou effacer vos informations à tout moment.</p>`;
const lview=()=>`<button class="chip" onclick="go('home')">← Accueil</button><h2>Informations légales</h2><p class="mu">Version de démonstration : ces textes doivent être validés par un juriste avant le lancement.</p>
<details class="c"><summary>Conditions d’utilisation</summary><ul><li>Service d’information, de première écoute et d’orientation.</li><li>Aucun diagnostic, aucune prescription, aucune prise en charge seule d’une urgence.</li><li>Les mineurs doivent avoir l’accord de leurs représentants légaux.</li><li>L’utilisateur reste responsable de sa décision de consulter.</li></ul></details>
<details class="c"><summary>Politique de confidentialité</summary><ul><li>Le profil santé et le suivi d’humeur du prototype sont enregistrés uniquement sur cet appareil.</li><li>Les données de compte et de rendez-vous sont transmises au serveur.</li><li>Vos messages à l’assistant ne sont pas enregistrés.</li><li>Version complète : consentement explicite, durée de conservation et formalités auprès de la CDP (loi n° 2008-12).</li></ul></details>
<details class="c"><summary>Mentions légales</summary><ul><li>Éditeur : Groupe 104, projet étudiant Sutura Santé (coach : M. Traoré).</li><li>Hébergeur et contact : à définir pour la version finale.</li></ul></details>
<details class="c"><summary>Mes données et mes droits</summary><p>${PR?`Profil : ${E(PR.p)} ${E(PR.n)}, ${PR.a} ans${PR.w==null?'':', '+fmt(PR.w)+' kg'}${PR.t==null?'':', '+fmt(PR.t)+' °C'}<br>`:''}${H.length?H.map(x=>`${x.d} : ${ML[x.v-1]}`).join('<br>'):'Aucune donnée enregistrée.'}</p><p class="mu">Accès : la liste ci-dessus. Rectification : enregistrez à nouveau votre humeur du jour. Suppression et opposition : boutons ci-dessous.</p><button class="b s" onclick="wipe()">Effacer mes données</button><button class="b s" onclick="withdraw()">Retirer mon consentement</button></details>`;
const V={home:hview,legal:lview,tech:tview,
fiches:()=>`<h2>Informations médicales</h2><input id="s" placeholder="Rechercher (ex. paludisme, stress)" oninput="list(this.value)" style="width:100%"><div id="fl"></div>`,
chat:()=>{if(!chat.length)chat.push({h:'<p>Bonjour ! Je peux donner des informations générales de santé et offrir une première écoute. Que souhaitez-vous savoir ?</p><p class="mu">Je ne pose pas de diagnostic et ne prescris aucun médicament. En cas d’urgence : SAMU 1515 ou pompiers 18.</p>'});return`<h2>Assistant Sutura</h2><p class="mu">Réponses issues de fiches générales. Ne remplace pas un professionnel.</p><div id="ms">${msgs()}</div>${chat.length<2?`<div class="chips" id="ch">${['Comment prévenir le paludisme ?','Comment gérer le stress des examens ?','J’ai de la fièvre','Je me sens triste'].map(x=>`<button class="chip" onclick="send(this.textContent)">${x}</button>`).join('')}</div>`:''}<form class="in" onsubmit="return send()"><input id="q" placeholder="Écrivez votre message…" autocomplete="off"><button class="b">Envoyer</button></form>`},
orient:oview,well:wview};
function render(){stopB();if(!OK||!P){$('#v').innerHTML=pform();$('#nav').innerHTML='';window.scrollTo(0,0);return}$('#v').innerHTML=V[tab]();$('#nav').innerHTML=TABS.map(t=>`<button class="${t[0]===tab?'on':''}" onclick="go('${t[0]}')"><span>${t[1]}</span>${t[2]}</button>`).join('');if(tab==='fiches')list('');window.scrollTo(0,0)}
render();
